use sqlx::{
    migrate::{Migrate, MigrateError, Migration, Migrator},
    query, query_scalar, Connection, PgConnection,
};
use tracing::info;

// Generated by build.rs from schema/bootstrap/postgres.
pub(crate) static EMPTY_DATABASE_SNAPSHOT_SQL: &str =
    include_str!(concat!(env!("OUT_DIR"), "/empty_database_snapshot.sql"));
// Fresh databases run only migrations newer than the snapshot.
pub(crate) const EMPTY_DATABASE_SNAPSHOT_CUTOFF_VERSION: i64 = 20261103000000;

// The snapshot is plain pg_dump output: only tables/indexes used to carry
// IF NOT EXISTS, and types, sequences, constraints and triggers never did.
// It is therefore safe only when the public schema has no user objects at all
// (apart from _sqlx_migrations, which the runner creates before calling us).
// pg_class covers tables, views, materialized views, sequences, foreign and
// partitioned tables and composite types; pg_type covers enum/domain/range
// types; pg_proc covers functions. Indexes are excluded because they always
// belong to a relation that pg_class already reports.
const HAS_PUBLIC_OBJECTS_SQL: &str = r#"
SELECT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_class AS c
    JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'v', 'm', 'S', 'f', 'p', 'c')
      AND c.relname <> '_sqlx_migrations'
    UNION ALL
    SELECT 1
    FROM pg_catalog.pg_type AS t
    JOIN pg_catalog.pg_namespace AS n ON n.oid = t.typnamespace
    WHERE n.nspname = 'public' AND t.typtype IN ('e', 'd', 'r')
    UNION ALL
    SELECT 1
    FROM pg_catalog.pg_proc AS p
    JOIN pg_catalog.pg_namespace AS n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
)
"#;
const INSERT_APPLIED_MIGRATION_SQL: &str = r#"
INSERT INTO _sqlx_migrations (
    version,
    description,
    success,
    checksum,
    execution_time
) VALUES (
    $1,
    $2,
    TRUE,
    $3,
    0
)
ON CONFLICT (version) DO NOTHING
"#;

pub(crate) async fn apply_snapshot_if_empty(
    conn: &mut PgConnection,
    migrator: &'static Migrator,
) -> Result<(), MigrateError> {
    if !should_apply_snapshot(conn, &migrator.table_name).await? {
        return Ok(());
    }

    let migrations = snapshot_migrations(migrator)?;
    info!(
        cutoff_version = EMPTY_DATABASE_SNAPSHOT_CUTOFF_VERSION,
        stamped_migrations = migrations.len(),
        "bootstrapping empty database from empty_database_snapshot"
    );

    let mut tx = conn.begin().await?;
    sqlx::raw_sql(EMPTY_DATABASE_SNAPSHOT_SQL)
        .execute(&mut *tx)
        .await?;
    for migration in migrations {
        query(INSERT_APPLIED_MIGRATION_SQL)
            .bind(migration.version)
            .bind(migration.description.as_ref())
            .bind(migration.checksum.as_ref())
            .execute(&mut *tx)
            .await?;
    }
    tx.commit().await?;

    Ok(())
}

pub(crate) async fn should_apply_snapshot(
    conn: &mut PgConnection,
    migrations_table: &str,
) -> Result<bool, MigrateError> {
    let applied_migrations = conn.list_applied_migrations(migrations_table).await?;
    if !applied_migrations.is_empty() {
        return Ok(false);
    }

    // Databases with any pre-existing public object fall through to the
    // normal, idempotent migration path instead of risking a half-applied or
    // silently wrong schema from the snapshot's unguarded DDL.
    let has_public_objects: bool = query_scalar(HAS_PUBLIC_OBJECTS_SQL)
        .fetch_one(&mut *conn)
        .await?;
    Ok(!has_public_objects)
}

pub(crate) fn snapshot_migrations(
    migrator: &'static Migrator,
) -> Result<Vec<&'static Migration>, MigrateError> {
    let migrations = migrator
        .iter()
        .filter(|migration| migration.migration_type.is_up_migration())
        .filter(|migration| migration.version <= EMPTY_DATABASE_SNAPSHOT_CUTOFF_VERSION)
        .collect::<Vec<_>>();

    if migrations.is_empty() {
        return Err(MigrateError::Source(Box::new(std::io::Error::other(
            "empty database snapshot cutoff does not match any embedded migrations",
        ))));
    }

    Ok(migrations)
}
